@router.post("/sso/saml/exchange-token")
async def exchange_saml_assertion_for_token(
    payload: SAMLExchangePayload,
    db: AsyncSession = Depends(get_db)
):
    auth = OneLogin_Saml2_Auth(payload.saml_request_data, get_global_saml_settings())
    auth.process_response()

    if auth.get_errors():
        raise HTTPException(status_code=401, detail="SAML verification failed")

    user_email = auth.get_nameid()
    user = await db.scalar(select(User).where(User.email == user_email))
    if not user:
        raise HTTPException(status_code=404, detail="User account not found")

    target_tenant = payload.audience_tenant or user.default_tenant
    tenant_member = await db.scalar(
        select(TenantMember).where(
            TenantMember.tenant_id == target_tenant,
            TenantMember.user_id == user.id
        )
    )
    if not tenant_member:
        raise HTTPException(status_code=403, detail="Forbidden: user is not authorized for target audience tenant")

    api_token = generate_scoped_jwt(user.id, target_tenant)
    return {"token": api_token, "audience": target_tenant}
